contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public test function with one parameter to range over
    function run(uint dummyAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        // Ensure we do NOT call c.deposit so this contract's recorded credit is zero.
        // Read balances before calling withdrawAll
        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;

        // Call withdrawAll and catch whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balC_after = address(c).balance;
        uint balThis_after = address(this).balance;

        // General rule: if we never deposited (so recorded credit for this caller is zero),
        // withdrawAll must not change ether balances of C or this contract.
        assert(balC_after == balC_before && balThis_after == balThis_before);
    }
    // allow receiving ether if needed by the environment
    receive() external payable {}
}

