// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 dummyAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balC_after = address(c).balance;
        uint balThis_after = address(this).balance;
        assertTrue(balC_after == balC_before && balThis_after == balThis_before);
    }

    function testFuzz_run(uint256 dummyAmount) public {
        _run(dummyAmount);
    }

    receive() external payable {}
}
